function debounce(fn, wait) {
    let t;
    return (...args) => {
        clearTimeout(t);
        t = setTimeout(() => fn.apply(this, args), wait);
    };
}

class CartRemove extends HTMLElement {
    constructor() {
        super();
        this.debouncedOnChange = debounce((element) => {
            const index = element.closest('cart-item').dataset.itemIndex;
            this.closest('cart-item').updateCart(index, 0);
            this.closest('.js-cart-page').classList.add('loading');
        }, 300);
        let _this = this
        this.addEventListener('click', (event) => {
            event.preventDefault();
            _this.debouncedOnChange(this)
        });
    }
}

customElements.define('remove-item', CartRemove);
class Cart extends HTMLElement{
    constructor() {
        super();
        this.input = this.querySelector('input[name="quantity"]');
        this.buttons = this.querySelectorAll('.js-quantity-input-button');
        this.debouncedOnChange = debounce((element) => {
            this.closest('.js-cart-page').classList.add('loading');
            let line= element.closest('cart-item').dataset.itemIndex;
            let quantity = element.closest('cart-item').querySelector('input[name="quantity"]').value;
            this.updateCart(line,quantity);
        }, 300);
        let _this = this
        if(this.input){
            this.input.addEventListener('change', function (){
                _this.debouncedOnChange(this)
            });
        }
        if(this.buttons){
            this.buttons.forEach(function (button){
                button.addEventListener('click', function (){
                    setTimeout(_this.debouncedOnChange(this), 0)
                });
            })
        }

    }

    updateCart(line,quantity) {
        const body = JSON.stringify({
            line: line,
            quantity: quantity
        });

        fetch(`${routes.cart_change_url}`, {...fetchConfig(), ...{ body }})
            .then((response) => {
                return response.text();
            })
            .then((state) => {
                const statejson =JSON.parse(state)
                if(statejson.errors){
                    this.errorMessage(statejson,line)
                    return
                }
                this.updateCartContent();
                console.log("success")

            }) .catch((e) => {
            console.error(e);
        });
    }
    errorMessage(resp,line){
		console.log(resp.errors)
    }
    updateCartContent(){
        fetch(window.routes.cart_url + '?section_id=template-cart')
            .then((response) => response.text())
            .then((responseText) => {
                const html = new DOMParser().parseFromString(responseText, 'text/html');
                const fetchCart = html.querySelector('.js-cart-page');
                // this.closest('.cart').classList.remove('loading');
                if(this.closest('.js-cart-page') && fetchCart){
                    this.closest('.js-cart-page').outerHTML = fetchCart.outerHTML;
                }

            })
            .catch(e => {
                console.error(e);
            });
    }
}
customElements.define('cart-item', Cart )



